CREATE DATABASE IF NOT EXISTS joepro_laravel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE joepro_laravel;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,role ENUM('tourist','operator') NOT NULL DEFAULT 'tourist',remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE packages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,location VARCHAR(255) NOT NULL,description TEXT NOT NULL,price DECIMAL(10,2) NOT NULL,duration VARCHAR(255) NOT NULL,difficulty VARCHAR(255) NOT NULL,capacity TINYINT UNSIGNED NOT NULL DEFAULT 12,available_dates JSON NULL,image_url TEXT NOT NULL,is_available BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE transports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_type VARCHAR(100) NOT NULL,capacity TINYINT UNSIGNED NOT NULL,roundtrip_price DECIMAL(10,2) NULL,dropoff_price DECIMAL(10,2) NULL,is_available BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL);
CREATE TABLE bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(255) NOT NULL UNIQUE,package_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,transport_id BIGINT UNSIGNED NULL,contact_number VARCHAR(30) NULL,tour_date DATE NOT NULL,guest_count TINYINT UNSIGNED NOT NULL,special_requests TEXT NULL,total_amount DECIMAL(10,2) NOT NULL,status ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(package_id) REFERENCES packages(id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(transport_id) REFERENCES transports(id) ON DELETE SET NULL,INDEX booking_schedule(package_id,tour_date,status));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,payment_method ENUM('gcash','bank_transfer','cash') NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending',reference_number VARCHAR(255) NULL,screenshot_url TEXT NULL,verified_by BIGINT UNSIGNED NULL,verified_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(verified_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NULL,message TEXT NOT NULL,type ENUM('booking','payment','system') NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NOT NULL UNIQUE,rating TINYINT UNSIGNED NOT NULL,comment TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE admin_review_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,review_id BIGINT UNSIGNED NOT NULL,admin_id BIGINT UNSIGNED NOT NULL,reply_text TEXT NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE,FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE);

